             CcRecipients = emailInfo.EmailCc;
             BccRecipients = emailInfo.EmailBcc;

             Subject = emailInfo.EmailSubject;

             EmailFormat = emailInfo.EmailFormat;
             Body = emailInfo.EmailBody;
             PlainTextBody = emailInfo.EmailPlainTextBody;

             foreach (Attachment attachment in EmailAttachmentInfo.Provider.GetAttachments(emailInfo.EmailID))
             {
                 Attachments.Add(attachment);
             }

             Headers = EmailHelper.GetHeaderFields(emailInfo.EmailHeaders);

             Priority = emailInfo.EmailPriority;

             EmailConfigurationID = emailInfo.EmailEmailConfigurationID;
             MailoutGuid = emailInfo.EmailMailoutGuid;
