 using Microsoft.AspNetCore.Mvc.Razor;
 using Microsoft.AspNetCore.Razor.Hosting;
 using Microsoft.Extensions.DependencyInjection;

 namespace Codesamples;

 /// <summary>
 /// Auto-discovers compiled views in the CodeSamples RCL and registers their locations.
 /// This allows views to be placed anywhere in the project structure.
