 public static class CodeSamplesViewDiscoveryExtensions
 {
     public static IServiceCollection AddCodeSamplesViews(this IServiceCollection services)
     {
         services.Configure<RazorViewEngineOptions>(options =>
         {
             // Get the CodeSamples assembly
             var rclAssembly = typeof(CodeSamplesViewDiscoveryExtensions).Assembly;

             // Find all compiled views in this assembly via RazorCompiledItemAttribute
             var compiledViews = rclAssembly
                 .GetCustomAttributes<RazorCompiledItemAttribute>()
                 .Select(attr => attr.Identifier)
                 .Where(id => !id.StartsWith("/Views/")) // Exclude Views/Shared copies
                 .ToList();

             // For each view, register:
             // Full hierarchical path (e.g., "DigitalCommerce/Promotions/Coupons/CouponCodeView")
             foreach (var viewPath in compiledViews)
             {
                 // Add full path support (without leading slash, without extension)
                 // /DigitalCommerce/Promotions/Coupons/CouponCodeView.cshtml 
                 // -> DigitalCommerce/Promotions/Coupons/CouponCodeView
                 var relativePath = viewPath.TrimStart('/').Replace(".cshtml", "");
                 var fullPathFormat = $"/{relativePath}.cshtml";
                 if (!options.ViewLocationFormats.Contains(fullPathFormat))
                 {
                     options.ViewLocationFormats.Add(fullPathFormat);
                 }
             }
         });

