17. public class PasswordResetController : Controller
18. {
19.     private readonly UserManager<ApplicationUser> userManager;
20.     private readonly IEmailService messageService;
21. 
22.     public PasswordResetController(UserManager<ApplicationUser> userManager,
23.                              IEmailService messageService)
24.     {
25.         this.userManager = userManager;
26.         this.messageService = messageService;
27.     }
28. 
29.     // Allows visitors to submit their email address and request a password reset
30.     public IActionResult PasswordResetRequest()
31.     {
32.         return View();
33.     }
34. 
35.     // Generates a password reset request for the specified email address.
36.     [HttpPost]
37.     [ValidateAntiForgeryToken]
38.     public async Task<IActionResult> RequestPasswordReset(PasswordResetRequestViewModel model)
39.     {
40.         // Validates the received email address based on the view model
41.         if (!ModelState.IsValid)
42.         {
43.             return View(model);
44.         }
45. 
46.         // Gets the user entity for the specified email address
47.         ApplicationUser user = await userManager.FindByEmailAsync(model.Email);
48. 
49.         if (user != null)
50.         {
51.             // Generates a password reset token for the user
52.             string token = await userManager.GeneratePasswordResetTokenAsync(user);
53. 
54.             // URL-encodes the token
55.             string encodedToken = WebUtility.UrlEncode(token);
56. 
57.             // Prepares the URL of the password reset link (targets the "PasswordReset" action)
58.             // Fill in the name of your controller
59.             string resetUrl = Url.Action(nameof(PasswordResetController.PasswordReset),
60.                                          "PasswordReset",
61.                                          new { userId = user.Id, token = encodedToken },
62.                                          Request.Scheme);
63. 
64.             // Creates and sends the password reset email to the user's address
65.             await messageService
66.                 .SendEmail(new EmailMessage()
67.                 {
68.                     From = "admin@localhost.local",
69.                     Recipients = user.Email,
70.                     Subject = "Password reset request",
71.                     Body = $"To reset your account's password, click <a href=\"{resetUrl}\">here</a>."
72.                 });
73.         }
74. 
75.         // Displays a view asking the visitor to check their email and click the password reset link.
76.         // General security practices recommend never confirming whether the reset email was sent successfully.
77.         // For this reason, the method always terminates by displaying a generic message.
78.         return RedirectToAction(nameof(CheckYourEmail));
79.     }
80. 
81.     public IActionResult CheckYourEmail()
82.     {
83.         return View();
84.     }
85. 
86.     // Handles the links that users click in password reset emails.
87.     // If the request parameters are valid, displays a form where users can reset their password.
88.     public async Task<IActionResult> PasswordReset(int? userId, string token)
89.     {
90.         // Handles the case when the token is missing from the URL
91.         if (String.IsNullOrEmpty(token))
92.         {
93.             return NotFound();
94.         }
95. 
96.         // Decodes the token from the URL
97.         token = WebUtility.UrlDecode(token);
98. 
99.         // Gets the member that requested the password reset
100.         ApplicationUser user = await userManager.FindByIdAsync(userId.ToString());
101. 
102.         try
103.         {
104.             // Verifies the parameters of the password reset request
105.             // True if the token is valid for the specified user, false if the token is invalid or has expired
106.             // By default, the generated tokens are single-use and expire in 1 day
107.             if (await userManager.VerifyUserTokenAsync(
108.                                     user: user,
109.                                     tokenProvider: userManager.Options.Tokens.PasswordResetTokenProvider,
110.                                     purpose: UserManager<ApplicationUser>.ResetPasswordTokenPurpose,
111.                                     token: token)
112.                )
113.             {
114.                 // If the password request is valid, displays the password reset form
115.                 ResetPasswordViewModel model = new ResetPasswordViewModel
116.                 {
117.                     UserId = userId.Value,
118.                     Token = token
119.                 };
120. 
121.                 return View(model);
122.             }
123. 
124.             // If the password request is invalid, returns a view informing the user
125.             return View("PasswordResetResult", ViewBag.Success = false);
