12. using SignInResult = Microsoft.AspNetCore.Identity.SignInResult;
13. 
14. namespace Codesamples.Membership.Standalone;
15. 
16. public class ExternalAuthController : Controller
17. {
18.     private readonly IEventLogService eventLogService;
19.     private readonly UserManager<ApplicationUser> userManager;
20.     private readonly SignInManager<ApplicationUser> signInManager;
21. 
22.     // Gets required services using dependency injection
23.     public ExternalAuthController(UserManager<ApplicationUser> userManager,
24.                              SignInManager<ApplicationUser> signInManager,
25.                              IEventLogService eventLogService)
26.     {
27.         this.userManager = userManager;
28.         this.signInManager = signInManager;
29.         this.eventLogService = eventLogService;
30.     }
31. 
32.     //Include:external-challenge
33.     // Redirects authentication requests to an external service
34.     [HttpPost]
35.     [ValidateAntiForgeryToken]
36.     public IActionResult RequestExternalSignIn(string provider)
37.     {
38.         // The URL to redirect to after successful authentication
39.         string redirectUrl = Url.Action(nameof(ExternalSignInCallback));
40. 
41.         // Configures the redirect URL and user identifier
42.         // for the specified external authentication provider
43.         AuthenticationProperties authenticationProperties =
44.             signInManager.ConfigureExternalAuthenticationProperties(provider, redirectUrl);
45. 
46.         // Challenges the specified authentication provider
47.         return Challenge(authenticationProperties, provider);
48.     }
49.     //EndInclude:external-challenge
50. 
51.     //Include:external-callback
52.     // Processes the response from external providers
53.     [HttpGet]
54.     public async Task<IActionResult> ExternalSignInCallback(string remoteError = null)
55.     {
56.         // Extracts login info out of the external identity provided by the service
57.         ExternalLoginInfo loginInfo = await signInManager.GetExternalLoginInfoAsync();
58. 
59.         // If the external authentication fails, displays a view with appropriate information
60.         if (loginInfo == null)
61.         {
62.             return RedirectToAction(nameof(ExternalAuthenticationFailure));
63.         }
64. 
65.         // Synchronizes the external account with Xperience's database
66.         await SynchronizeExternalAccount(loginInfo);
67. 
68.         return Redirect($"/");
69.     }
70.     //EndInclude:external-callback
71. 
72.     //Include:external-sync
73.     private async Task SynchronizeExternalAccount(ExternalLoginInfo loginInfo)
74.     {
75.         string providerKey = loginInfo.ProviderKey;
76. 
77.         // If the external login doesn't exist in the database either a new
78.         // visitor is signing in or an existing visitor is signing in using a different provider
79.         if (await userManager.FindByLoginAsync(loginInfo.LoginProvider, providerKey) == null)
80.         {
81.             // Gets an email from external claims
82.             string email = loginInfo.Principal.FindFirstValue(ClaimTypes.Email);
83. 
84.             // Checks whether the account already exists
85.             // Uses the email address as a common link among multiple providers
86.             ApplicationUser user = await userManager.FindByEmailAsync(email);
87.             UserLoginInfo login = new UserLoginInfo(loginInfo.LoginProvider, providerKey, null);
88. 
89.             if (user != null)
90.             {
91.                 // If the account already exists the visitor is using a different
92.                 // external provider. Bind the new external login to an existing account.
93.                 await userManager.AddLoginAsync(user, login);
94.                 await SignInExternal(loginInfo);
95.             }
96.             else
97.             {
98.                 // Otherwise, a completely new visitor is signing in.
99.                 // Create their account and corresponding external login.
100. 
101.                 // Creates the user object
102.                 user = new ApplicationUser
103.                 {
104.                     // Accounts must be enabled to be granted access to the system
105.                     // For external accounts, it is safe to always set this property to true
106.                     // without implementing additional verification measures.
107.                     // The external provider ensures authenticity of the received data.
108.                     Enabled = true,
109.                     Email = email,
110.                     UserName = email,
111.                     // Flag to identify external accounts
112.                     IsExternal = true
113.                 };
114. 
115.                 // Creates the user account
116.                 await userManager.CreateAsync(user);
117.                 // Binds the external login to the created account
118.                 await userManager.AddLoginAsync(user, login);
119.                 await SignInExternal(loginInfo);
120.             }
121.         }
122.         // Otherwise, sign in the visitor
123.         else
124.         {
125.             await SignInExternal(loginInfo);
126.         }
127.     }
128. 
129.     private async Task SignInExternal(ExternalLoginInfo loginInfo)
130.     {
131.         // Attempts to sign in the user using the external login info
132.         SignInResult result =
133.             await signInManager.
134.                 ExternalLoginSignInAsync(loginInfo.LoginProvider, loginInfo.ProviderKey, true);
135. 
136.         // Success occurs if the user already exists in the connected database
137.         // and has signed in using the given external service
138.         if (result.Succeeded)
139.         {
140.             eventLogService.LogInformation("ExternalAuthController", "EXTERNALAUTH",
141.                 $"Visitor signed in via {loginInfo.LoginProvider}");
142.         }
143.         else
144.         {
145.             eventLogService.LogWarning("ExternalAuthController", "EXTERNALAUTH_ERROR",
146.                 "External sign in error");
147.         }
148.     }
149.     //EndInclude:external-sync
150. 
151.     public IActionResult ExternalAuthenticationFailure()
152.     {
153.         return View();
154.     }
155. }
156.

