 ﻿using System;

 using Microsoft.AspNetCore.Builder;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.AspNetCore.Identity;

 using Kentico.Web.Mvc;
 using Kentico.Membership;
 using Kentico.Commerce.Web.Mvc;
 using Kentico.Content.Web.Mvc.Routing;

 using Codesamples;
 using Codesamples.Extensions;
 using Codesamples.Initialization;

 var builder = WebApplication.CreateBuilder(args);

 // Enable desired Kentico Xperience features
 builder.Services.AddKentico(features =>
 {
     features.UseCommerce();
     features.UseWebPageRouting();
 });

 // Configures admin UI authentication
 builder.Services.Configure<AdminIdentityOptions>(options =>
 {
     options.AuthenticationOptions.ExpireTimeSpan = TimeSpan.FromDays(31);
 });

 //Include:identity-setup
 // Adds and configures ASP.NET Identity for the application
 builder.Services.AddIdentity<ApplicationUser, NoOpApplicationRole>(options =>
 {
     // Ensures that disabled member accounts cannot sign in
     options.SignIn.RequireConfirmedAccount = true;
     // Ensures unique emails for registered accounts
     options.User.RequireUniqueEmail = true;

     options.Password.RequireDigit = false;
     options.Password.RequireNonAlphanumeric = false;
     options.Password.RequiredLength = 4;
     options.Password.RequireUppercase = false;
     options.Password.RequireLowercase = false;
 })
     .AddUserStore<ApplicationUserStore<ApplicationUser>>()
     .AddRoleStore<NoOpApplicationRoleStore>()
     .AddUserManager<UserManager<ApplicationUser>>()
     .AddSignInManager<SignInManager<ApplicationUser>>();
 //EndInclude:identity-setup

 builder.Services.AddAuthentication();
 // builder.Services.AddAuthorization();

 builder.Services.AddAndConfigureCommerceServices();

 // Register controllers from CodeSamples assembly for discovery
 builder.Services.AddControllersWithViews()
     .AddApplicationPart(typeof(CodeSamplesMarker).Assembly);

 // Auto-discover and register views from CodeSamples RCL
 builder.Services.AddCodeSamplesViews();

 var app = builder.Build();
 app.InitKentico();

 if (await ProjectInitializer.RunAsync(app.Services))
 {
     return;
 }

 //Include:middleware-setup
 app.UseStaticFiles();

 app.UseCookiePolicy();

 app.UseAuthentication();

 app.UseKentico();

 app.UseAuthorization();
 //EndInclude:middleware-setup

 app.Kentico().MapRoutes();

 app.MapControllerRoute(
     name: "default",
     pattern: "{controller=Home}/{action=Index}/{id?}");

 app.Run();

