     context 'when exclude parameter is provided' do
       it 'excludes the specified section from the entire file' do
         # Create file with sections to exclude
         exclude_file = File.join(fixtures_path, 'with_excludable.cs')
         File.write(exclude_file, <<~CS)
           public class Example
           {
               public string Name { get; set; }

               //Include:internal
               // This is internal implementation
               private void InternalMethod() { }
               //EndInclude:internal

               public void PublicMethod() { }
           }
         CS

         template = Liquid::Template.parse('{% code_link source="with_excludable.cs" lang="csharp" exclude="internal" %}')
         output = template.render(context)

         expect(output).to include('public class Example')
         expect(output).to include('public string Name')
         expect(output).to include('public void PublicMethod')
         expect(output).not_to include('InternalMethod')
         expect(output).not_to include('internal implementation')

         FileUtils.rm_f(exclude_file)
       end

       it 'excludes a nested section when using id and exclude together' do
         # Create file with nested sections
         nested_file = File.join(fixtures_path, 'nested_sections.cs')
         File.write(nested_file, <<~CS)
           //Include:outer
           public class Service
           {
               public string Name { get; set; }

               //Include:debug
               // Debug logging - exclude from docs
               private void LogDebug() { }
               //EndInclude:debug

               public void Process() { }
           }
           //EndInclude:outer
         CS

         template = Liquid::Template.parse('{% code_link source="nested_sections.cs" lang="csharp" id="outer" exclude="debug" %}')
         output = template.render(context)

         expect(output).to include('public class Service')
         expect(output).to include('public string Name')
         expect(output).to include('public void Process')
         expect(output).not_to include('LogDebug')
         expect(output).not_to include('Debug logging')

         FileUtils.rm_f(nested_file)
       end

       it 'excludes multiple sections with comma-separated IDs' do
         # Create file with multiple excludable sections
         multi_exclude_file = File.join(fixtures_path, 'multi_exclude.cs')
         File.write(multi_exclude_file, <<~CS)
           public class Example
           {
               public string Name { get; set; }

               //Include:debug
               private void Debug1() { }
               //EndInclude:debug

               public void PublicMethod() { }

               //Include:test
               private void TestHelper() { }
               //EndInclude:test
           }
         CS

         template = Liquid::Template.parse('{% code_link source="multi_exclude.cs" lang="csharp" exclude="debug,test" %}')
         output = template.render(context)

         expect(output).to include('public class Example')
         expect(output).to include('public string Name')
         expect(output).to include('public void PublicMethod')
         expect(output).not_to include('Debug1')
         expect(output).not_to include('TestHelper')

         FileUtils.rm_f(multi_exclude_file)
       end

       it 'handles spaces around commas in exclude IDs' do
         exclude_file = File.join(fixtures_path, 'spaces_exclude.cs')
         File.write(exclude_file, <<~CS)
           public class Example
           {
               //Include:a
               private void A() { }
               //EndInclude:a

               public void Keep() { }

               //Include:b
               private void B() { }
               //EndInclude:b
           }
         CS

         template = Liquid::Template.parse('{% code_link source="spaces_exclude.cs" lang="csharp" exclude="a, b" %}')
         output = template.render(context)

