             IUserManagementService userManagementService)
             : base(userManager, contextAccessor, claimsFactory,
                   AdminIdentityOptionsHelper.CreateIdentityOptions(optionsAccessor, dataProtectionProvider, dataProtectionLogger, authenticatorTokenProvider), logger, schemes, confirmation)
         {
