                 return error;
             }

             if (await UserManager.VerifyTwoFactorTokenAsync(user, Options.Tokens.AuthenticatorTokenProvider, code))
             {
                 var claims = GetMultifactorClaims();

                 await Context.SignOutAsync(AdminIdentityConstants.TWO_FACTOR_USER_ID_SCHEME);
                 await SignInWithClaimsAsync(user, isPersistent, claims);
                 await UserManager.ResetAccessFailedCountAsync(user);

                 return SignInResult.Success;
             }

             return SignInResult.Failed;
         }


         /// <inheritdoc/>
         protected override async Task<SignInResult> SignInOrTwoFactorAsync(AdminApplicationUser user, bool isPersistent, string loginProvider = null, bool bypassTwoFactor = false)
         {
             if (!bypassTwoFactor && await IsMfaEnabled(user) && !await IsTwoFactorClientRememberedAsync(user))
             {
                 if (await schemes.GetSchemeAsync(AdminIdentityConstants.TWO_FACTOR_USER_ID_SCHEME) != null)
                 {
                     // Store the userId for use after two factor check
                     var userId = await UserManager.GetUserIdAsync(user);
                     await Context.SignInAsync(AdminIdentityConstants.TWO_FACTOR_USER_ID_SCHEME, GetMultiFactorClaims(userId, loginProvider));
                 }

                 return SignInResult.TwoFactorRequired;
             }

             if (loginProvider != null)
             {
                 await Context.SignOutAsync(AdminIdentityConstants.EXTERNAL_SCHEME);
             }

             if (loginProvider == null)
             {
                 await SignInWithClaimsAsync(user, isPersistent, new Claim[] { new Claim("amr", "pwd") });
             }
             else
             {
                 await SignInAsync(user, isPersistent, loginProvider);
             }

             return SignInResult.Success;
         }


         /// <inheritdoc/>
         public override async Task<bool> IsTwoFactorClientRememberedAsync(AdminApplicationUser user)
         {
             var userId = await UserManager.GetUserIdAsync(user);
             var result = await Context.AuthenticateAsync(AdminIdentityConstants.TWO_FACTOR_REMEMBER_ME_SCHEME);

             return result?.Principal != null && result.Principal.FindFirstValue(ClaimTypes.Name) == userId;
         }


         /// <summary>
         /// Determines whether the two factor authenticating user has requested reset of the authenticator key.
         /// </summary>
         public virtual async Task<bool> IsTwoFactorAuthenticationKeyResetRequestedAsync()
         {
             var user = await GetTwoFactorAuthenticationUserAsync();
             if (user is null)
             {
                 return false;
             }

             return await UserManager.GetTwoFactorEnabledAsync(user) && user.UserAuthenticatorSharedKeyResetRequested;
         }


         /// <summary>
         /// Indicated whether the external authentication is configured in <see cref="AdminAuthenticationMode.PrioritizeExternal"/> mode.
         /// </summary>
         public virtual bool IsExternalModeOnly()
         {
             return adminExternalProviderOptions.IsExternalProviderConfigured() && adminIdentityOptions.AuthenticationOptions.Mode == AdminAuthenticationMode.PrioritizeExternal;
         }


         private static List<Claim> GetMultifactorClaims()
         {
             return new List<Claim>
                 {
                     new Claim(MULTIFACTOR_CLAIM_NAME, "mfa")
                 };
         }


         private static ClaimsPrincipal GetMultiFactorClaims(string userId, string loginProvider)
         {
             var identity = new ClaimsIdentity(AdminIdentityConstants.TWO_FACTOR_USER_ID_SCHEME);
             identity.AddClaim(new Claim(ClaimTypes.Name, userId));

             if (loginProvider != null)
             {
                 identity.AddClaim(new Claim(ClaimTypes.AuthenticationMethod, loginProvider));
             }

             return new ClaimsPrincipal(identity);
         }


         private async Task<bool> IsMfaEnabled(AdminApplicationUser user)
         {
             return UserManager.SupportsUserTwoFactor && await UserManager.GetTwoFactorEnabledAsync(user) && (await UserManager.GetValidTwoFactorProvidersAsync(user)).Count > 0;
         }


         private bool IsSendingUserAccountLockoutEmail(AdminApplicationUser user)
         {
             var lockoutEnd = progressiveCache.Load((cacheSettings) => user.GetValue<DateTime?>(nameof(CMS.Membership.UserInfo.UserLockoutEnd), null), new CacheSettings(60, user.UserGUID.ToString()));

             return lockoutEnd.HasValue;
         }


         private static string[] GetUserCacheKeys(AdminApplicationUser user)
         {
             return user.Generalized.GetCacheDependencies().ToArray();
         }
     }
 }

